import json,random,math
from collections import Counter,defaultdict,deque
from pathlib import Path
from vs import corpus, ivtff

ALPHABET = frozenset("acdefghiklmnopqrsty")

def eligible(line):
    return line.unit == "P" and line.words and all(
        not ivtff.uncertain(word) and set(word) <= ALPHABET for word in line.words
    )

data = {edition: corpus.split_pages("practice", edition) for edition in ("zl", "it")}
keep = set.intersection(*(
    {line.id for page in practice for line in page.lines if eligible(line)}
    for _, practice in data.values()
))

def metrics(pages, sections):
    counts=[Counter(page) for page in pages]
    total=sum(counts,Counter())
    def matches(group):
        return sum(n*(n-1) for n in group.values())
    sizes=list(map(len,pages))
    n=sum(sizes)
    baseline=matches(total)/(n*(n-1))
    local=sum(map(matches,counts))/sum(n*(n-1) for n in sizes)/baseline
    def mi(tags, page_counts):
        groups=defaultdict(Counter)
        for tag, count in zip(tags,page_counts):
            groups[tag].update(count)
        return sum(
            v/n*math.log2(v*n/(group_size*total[w]))
            for g in groups.values()
            for group_size in [g.total()]
            for w,v in g.items()
        )
    shuffled=sections[:]
    rng=random.Random(314)
    null=[]
    for _ in range(39):
        rng.shuffle(shuffled)
        null.append(mi(shuffled,counts))
    observed=mi(sections,counts)
    rotations=[mi(sections[i:]+sections[:i],counts) for i in range(len(sections))]
    words=[word for page in pages for word in page]
    global_null=[]
    for _ in range(39):
        rng.shuffle(words)
        offset=0
        rand_pages=[]
        for length in sizes:
            rand_pages.append(Counter(words[offset:offset+length]))
            offset+=length
        global_null.append(mi(sections,rand_pages))
    return {
        "within_page_collision_ratio": local,
        "section_mi_bits": observed,
        "section_mi_excess_over_page_label_shuffles": observed-sum(null)/len(null),
        "page_label_shuffle_p": (1+sum(x>=observed for x in null))/40,
        "cyclic_label_p": sum(x>=observed for x in rotations)/len(rotations),
        "section_mi_excess_over_token_shuffles": observed-sum(global_null)/len(global_null),
        "token_shuffle_p": (1+sum(x>=observed for x in global_null))/40,
    }
def generate(sizes, vocabulary, weights, seed, memory_size, reset_every):
    rng=random.Random(seed)
    proposals=iter(rng.choices(vocabulary, weights, k=sum(sizes)))
    memory=deque(maxlen=memory_size)
    result=[]
    for index,n in enumerate(sizes):
        if reset_every and index%reset_every==0:
            memory.clear()
        page=[]
        for _ in range(n):
            word=next(proposals)
            if memory and rng.random()<0.33:
                word=rng.choice(memory)
            page.append(word)
            memory.append(word)
        result.append(page)
    return result
def main():
    result={}
    for edition,(fit,practice) in data.items():
        retained=[p for p in practice if any(l.id in keep for l in p.lines)]
        pages=[[w for line in p.lines if line.id in keep for w in line.words] for p in retained]
        sections=[p.section for p in retained]
        sizes=list(map(len,pages))
        prior=Counter(w for p in fit for line in p.lines if eligible(line) for w in line.words)
        v=sorted(prior)
        weights=[prior[w] for w in v]
        controls={}
        for size,reset in [(0,0),(30,0),(180,0),(720,0),(180,5)]:
            controls[f'{size}:{reset}']=[metrics(generate(sizes,v,weights,s,size,reset),sections) for s in range(201,217)]
        result[edition]={'pages':len(pages),'loci':len(keep),'tokens':sum(sizes),'actual':metrics(pages,sections),'controls':controls}
        print(edition,result[edition]['actual'],flush=True)
        Path('/tmp/fleet-sol-long-session.json').write_text(json.dumps(result,indent=2))
if __name__=='__main__':
    main()
